def register(api_router, db, deps):
    require_admin = deps["require_admin"]
    get_current_user = deps["get_current_user"]
    import fieldops

    async def _g():
        return await db.app_settings.find_one({"_id": "global"}, {"_id": 0}) or {}

    async def _job(jid, user):
        j = await db.service_jobs.find_one({"id": jid}, {"_id": 0})
        if not j:
            raise HTTPException(404, "Servis kaydı bulunamadı")
        if user.get("role") != "admin" and j.get("assigned_technician_id") != user.get("id"):
            raise HTTPException(403, "Bu kayıt size atanmamış")
        return j

    async def _admins():
        return [u["id"] async for u in db.users.find({"role": "admin"}, {"_id": 0, "id": 1})]

    def _clean_sig(s):
        s = str(s or "")
        if s.startswith("data:image/") and ";base64," in s[:40] and len(s) <= 260_000:
            return s
        return ""

    def _clean_photos(ph):
        out, tot = [], 0
        for x in (ph if isinstance(ph, list) else [])[:6]:
            x = str(x or "")
            if x.startswith("data:image/") and ";base64," in x[:40] and len(x) <= 450_000 and tot + len(x) <= 1_800_000:
                out.append(x)
                tot += len(x)
        return out

    def _summary(j, techs):
        w = j.get("workshop") or {}
        taken = w.get("taken_at")
        days = 0
        try:
            end = datetime.fromisoformat(w["delivered_at"]) if w.get("delivered_at") else datetime.now(timezone.utc)
            days = max(0, (end - datetime.fromisoformat(taken)).days)
        except Exception:
            pass
        return {"id": j["id"], "job_number": j.get("job_number"), "customer": j.get("customer_name"), "phone": j.get("customer_phone"), "address": j.get("customer_address"),
                "device": " ".join(x for x in [j.get("device_brand_name"), j.get("device_model"), j.get("device_type")] if x), "serial": j.get("device_serial"), "fault": (j.get("fault_description") or "")[:200],
                "tech": techs.get(w.get("taken_by_id") or j.get("assigned_technician_id"), w.get("taken_by_name", "")), "tech_id": j.get("assigned_technician_id"), "job_status": j.get("status"),
                "state": w.get("state"), "state_tr": STATES.get(w.get("state"), ""), "receipt_no": w.get("receipt_no"), "token": w.get("token"), "taken_at": taken, "reason": w.get("reason"),
                "condition": w.get("condition"), "accessories": w.get("accessories"), "damage": w.get("damage"), "est_ready": w.get("est_ready"), "price_estimate": w.get("price_estimate"),
                "days": days, "late": bool(w.get("state") == "atolyede" and days >= 7), "ready_at": w.get("ready_at"), "delivered_at": w.get("delivered_at"), "tech_note": w.get("tech_note", ""),
                "has_signature": bool(w.get("signature")), "has_tech_signature": bool(w.get("tech_signature")), "photo_count": len(w.get("photos") or []), "history": w.get("history", [])}

    async def _techs():
        return {u["id"]: u.get("name", "") async for u in db.users.find({"role": "technician"}, {"_id": 0, "id": 1, "name": 1})}

    @api_router.post("/workshop/{jid}/intake")
    async def intake(jid: str, payload: dict, user: dict = Depends(get_current_user)):
        j = await _job(jid, user)
        old = j.get("workshop") or {}
        if user.get("role") != "admin" and j.get("status") != "basladi":
            raise HTTPException(400, "Atölyeye almak için önce müşteride işe başlayın (adımları ilerletin)")
        if old.get("state") in ("atolyede", "hazir"):
            raise HTTPException(400, "Bu cihaz zaten atölyede kayıtlı")
        reason = str(payload.get("reason") or "").strip()[:200]
        if not reason:
            raise HTTPException(422, "Atölyeye alınma nedenini seçin")
        csig, tsig = _clean_sig(payload.get("signature")), _clean_sig(payload.get("tech_signature"))
        if not csig:
            raise HTTPException(422, "Müşteri imzası zorunlu")
        if not tsig:
            raise HTTPException(422, "Teknisyen imzası zorunlu")
        photos = _clean_photos(payload.get("photos"))
        if not photos:
            raise HTTPException(422, "Cihazın en az bir fotoğrafı zorunlu")
        if not payload.get("consent"):
            raise HTTPException(422, "Müşteri onayı (cihazın alınmasını kabul) işaretlenmeli")
        now = datetime.now(TR)
        n = await db.service_jobs.count_documents({"workshop.receipt_no": {"$regex": "^ATL-" + now.strftime("%y%m%d")}})
        rno = f"ATL-{now.strftime('%y%m%d')}-{n + 1:03d}"
        w = {"state": "atolyede", "receipt_no": rno, "token": secrets.token_urlsafe(14), "taken_at": _now(), "taken_by_id": user["id"], "taken_by_name": user.get("name", ""),
             "reason": reason, "condition": str(payload.get("condition") or "")[:500], "accessories": str(payload.get("accessories") or "")[:300], "damage": str(payload.get("damage") or "")[:500],
             "est_ready": str(payload.get("est_ready") or "")[:60], "price_estimate": str(payload.get("price_estimate") or "")[:30], "tech_note": str(payload.get("note") or "")[:500],
             "signature": csig, "tech_signature": tsig, "photos": photos, "history": [{"at": _now(), "state": "atolyede", "by": user.get("name", ""), "note": reason, "public": False}]}
        await db.service_jobs.update_one({"id": jid}, {"$set": {"workshop": w, "updated_at": _now()}})
        await fieldops.push_to(db, await _admins(), "🔧 Cihaz atölyeye alındı", f"{rno} · {j.get('customer_name', '')} · {j.get('device_type', '')} · {user.get('name', '')}", "/admin?ek=atolye")
        return {"ok": True, "receipt_no": rno, "token": w["token"], "print": f"/atolye/{w['token']}?fmt=a4"}

    @api_router.post("/workshop/{jid}/state")
    async def set_state(jid: str, payload: dict, user: dict = Depends(get_current_user)):
        j = await _job(jid, user)
        w = j.get("workshop") or {}
        st = payload.get("state")
        if not w or st not in STATES:
            raise HTTPException(422, "Geçersiz durum")
        note = str(payload.get("note") or "")[:300]
        upd = {"workshop.state": st, "updated_at": _now()}
        if st == "hazir":
            upd["workshop.ready_at"] = _now()
        if st == "teslim":
            upd["workshop.delivered_at"] = _now()
            sig = _clean_sig(payload.get("signature"))
            if sig:
                upd["workshop.delivery_signature"] = sig
        hist = {"at": _now(), "state": st, "by": user.get("name", ""), "note": note, "public": bool(payload.get("public", False))}
        await db.service_jobs.update_one({"id": jid}, {"$set": upd, "$push": {"workshop.history": hist}})
        if st == "hazir":
            await fieldops.push_to(db, await _admins(), "✅ Atölyedeki cihaz hazır", f"{w.get('receipt_no')} · {j.get('customer_name', '')} — müşteriye haber verin", "/admin?ek=atolye")
        return {"ok": True, "state": st}

    @api_router.post("/workshop/{jid}/note")
    async def add_note(jid: str, payload: dict, user: dict = Depends(get_current_user)):
        j = await _job(jid, user)
        if not j.get("workshop"):
            raise HTTPException(404, "Atölye kaydı yok")
        txt = str(payload.get("note") or "").strip()[:300]
        if not txt:
            raise HTTPException(422, "Not boş")
        await db.service_jobs.update_one({"id": jid}, {"$push": {"workshop.history": {"at": _now(), "state": (j["workshop"].get("state")), "by": user.get("name", ""), "note": txt, "public": bool(payload.get("public"))}}})
        return {"ok": True}

    @api_router.get("/workshop")
    async def wlist(state: str = "", user: dict = Depends(get_current_user)):
        q = {"workshop.state": {"$in": [state] if state in STATES else ["atolyede", "hazir"]}}
        if user.get("role") != "admin":
            q["assigned_technician_id"] = user["id"]
        elif state == "teslim":
            q["workshop.delivered_at"] = {"$gte": (datetime.now(timezone.utc) - timedelta(days=60)).isoformat()}
        rows = await db.service_jobs.find(q, {"_id": 0, "photos_before": 0, "photos_after": 0, "signature_url": 0, "tech_signature_url": 0, "workshop.signature": 0, "workshop.tech_signature": 0, "workshop.photos": 0, "workshop.delivery_signature": 0}).to_list(2000)
        techs = await _techs()
        out = [_summary(j, techs) for j in rows]
        out.sort(key=lambda r: r.get("taken_at") or "", reverse=True)
        if user.get("role") != "admin":
            for r in out:
                r.pop("history", None)
        return {"rows": out, "counts": {"atolyede": sum(1 for r in out if r["state"] == "atolyede"), "hazir": sum(1 for r in out if r["state"] == "hazir"), "late": sum(1 for r in out if r["late"])}, "reasons": REASONS}

    @api_router.get("/workshop/{jid}")
    async def wget(jid: str, user: dict = Depends(get_current_user)):
        j = await _job(jid, user)
        return {"workshop": _summary(j, await _techs()) if j.get("workshop") else None, "reasons": REASONS, "job": {"id": j["id"], "customer": j.get("customer_name"), "phone": j.get("customer_phone"), "device": " ".join(x for x in [j.get("device_brand_name"), j.get("device_model"), j.get("device_type")] if x), "status": j.get("status")}}

    @api_router.get("/workshop/{jid}/photos")
    async def wphotos(jid: str, user: dict = Depends(get_current_user)):
        j = await _job(jid, user)
        w = j.get("workshop") or {}
        return {"photos": w.get("photos", []), "signature": w.get("signature", ""), "tech_signature": w.get("tech_signature", ""), "delivery_signature": w.get("delivery_signature", "")}

    # ---- belirteçle açılan herkese açık (QR/yazdırma) uçları
    @api_router.get("/public/atolye/{token}/escpos")
    async def pub_escpos(token: str, w: int = 58, cp: str = "857", base: str = ""):
        j = await db.service_jobs.find_one({"workshop.token": token}, {"_id": 0})
        if not j:
            raise HTTPException(404, "Kayıt yok")
        v = _view(j, await _g())
        data = _escpos(v, 80 if w == 80 else 58, "ascii" if cp == "ascii" else "857", f"https://bayi.servisplus.net.tr/atolye/{token}?fmt=durum")
        return {"b64": base64.b64encode(data).decode(), "bytes": len(data)}

    @api_router.get("/public/atolye/{token}/text")
    async def pub_text(token: str, cols: int = 80):
        j = await db.service_jobs.find_one({"workshop.token": token}, {"_id": 0})
        if not j:
            raise HTTPException(404, "Kayıt yok")
        v = _view(j, await _g())
        cols = max(32, min(cols, 96))
        return PlainTextResponse("\n".join(_lines(v, cols, f"https://bayi.servisplus.net.tr/atolye/{token}?fmt=durum")), headers={"Cache-Control": "no-store"})


def page_handler(db):
    async def handler(token: str, fmt: str = "a4", auto: int = 0, request=None):
        j = await db.service_jobs.find_one({"workshop.token": token}, {"_id": 0})
        if not j:
            return HTMLResponse("<meta charset=utf-8><body style='font:16px sans-serif;padding:24px'>Bu bağlantı geçersiz.</body>", status_code=404)
        g = await db.app_settings.find_one({"_id": "global"}, {"_id": 0}) or {}
        base = f"{request.url.scheme}://{request.headers.get('host', request.url.netloc)}" if request else ""
        return render_page(j, g, fmt if fmt in ("a4", "t80", "t58", "nokta", "durum") else "a4", base, bool(auto))
    return handler


async def ensure_indexes(db):
    try:
        await db.service_jobs.create_index("workshop.token", sparse=True)
        await db.service_jobs.create_index("workshop.state", sparse=True)
    except Exception:
        pass

app/livechat.py:
# -*- coding: utf-8 -*-
"""Canli destek (site sohbeti).
Ziyaretci sitedeki 'Canli Destek' penceresine ad, telefon ve mesaj yazar -> sohbet acilir, otomatik karsilama mesaji gider.
Yoneticiler panelde 'Canli Sohbet' ekraninda konusur; yeni ziyaretci mesajinda admin bildirimi (push) gider.
Ziyaretci sohbeti bir gizli 'token' ile okur/yazar (sadece kendi tarayicisinda saklanir)."""
import secrets
import uuid
from datetime import datetime, timedelta, timezone

from fastapi import Depends, HTTPException, Request

WELCOME = "Merhaba {ad}, hoş geldiniz. Müsait olan temsilci en kısa sürede size yardımcı olacaktır."
AUTO_REPLY = WELCOME  # yonetici "Otomatik cevap" butonu ayni karsilamayi gonderir

# Yonetici "Otomatik cevap gonder"e basinca secilen hazir mesajlar. {ad} musterinin adiyla degisir.
DEFAULT_QUICK = [
    ("Karşılama", WELCOME),
    ("Cihaz bilgisi iste", "Merhaba {ad}, size daha iyi yardımcı olabilmemiz için cihazınızın markasını, modelini ve yaşadığınız arızayı yazar mısınız?"),
    ("Adres / bölge iste", "Merhaba {ad}, servis planlayabilmemiz için ilçe ve mahalle bilginizi paylaşır mısınız?"),
    ("Randevu saati sor", "Merhaba {ad}, size uygun bir servis randevusu ayarlayalım. Hangi gün ve saat aralığı sizin için uygun?"),
    ("Sizi arıyoruz", "Merhaba {ad}, sizi birazdan telefonla arayacağız. Telefonunuzun yakınında olabilir misiniz?"),
    ("Mesai dışı", "Merhaba {ad}, şu an mesai saatlerimiz dışındayız. Mesajınızı aldık, ilk fırsatta size dönüş yapacağız."),
    ("Teşekkür / kapanış", "Bizi tercih ettiğiniz için teşekkür ederiz {ad}. Başka bir sorunuz olursa buradan yazabilirsiniz."),
]


def _now():
    return datetime.now(timezone.utc).isoformat()


def _recent(ts, secs):
    """ISO zaman damgasi son `secs` saniye icinde mi? (yazıyor / çevrimiçi göstergeleri için)"""
    try:
        return bool(ts) and (datetime.now(timezone.utc) - datetime.fromisoformat(ts)).total_seconds() <= secs
    except Exception:
        return False


def _first(name: str) -> str:
    return (name or "").strip().split(" ")[0] if name else ""


def register(api_router, db, deps):
    get_current_user = deps["get_current_user"]

    async def _admin(user):
        if user.get("role") != "admin":
            raise HTTPException(403, "Yetkisiz")

    async def _notify(title, body):
        try:
            import notify as _n
            await _n.push_admins_t(db, title, body, "/admin?ek=sohbet")
        except Exception:
            pass

    async def _add(chat_id, sender, text):
        doc = {"id": str(uuid.uuid4()), "chat_id": chat_id, "from": sender, "text": text[:1000], "at": _now()}
        await db.live_messages.insert_one(doc)
        return doc

    async def _chat_for_visitor(cid, token):
        c = await db.live_chats.find_one({"id": cid}, {"_id": 0})
        if not c or not token or not secrets.compare_digest(str(c.get("token", "")), str(token)):
            raise HTTPException(404, "Sohbet bulunamadı")
        return c

    # ---------- ziyaretci (site) ----------
    @api_router.post("/public/chat/start")
    async def chat_start(payload: dict):
        name = str(payload.get("name") or "").strip()[:80]
        phone = "".join(ch for ch in str(payload.get("phone") or "") if ch.isdigit())[:15]
        page = str(payload.get("page") or "")[:200]
        brand = str(payload.get("brand") or "")[:60]
        first_msg = str(payload.get("message") or "").strip()[:1000]
        if len(name) < 3 or len(phone) < 10:
            raise HTTPException(422, "Ad soyad ve telefon gerekli")
        cid = str(uuid.uuid4())
        token = secrets.token_urlsafe(24)
        now = _now()
        await db.live_chats.insert_one({
            "id": cid, "token": token, "name": name, "phone": phone, "page": page, "brand": brand,
            "status": "acik", "created_at": now, "updated_at": now, "unread_admin": 1, "last_text": first_msg or WELCOME.format(ad=_first(name)),
        })
        # otomatik karsilama (sistem mesaji)
        await _add(cid, "bot", WELCOME.format(ad=_first(name)))
        if first_msg:
            await _add(cid, "visitor", first_msg)
        await _notify("Yeni canlı sohbet", f"{name} · {phone}" + (f" · {brand}" if brand else ""))
        return {"ok": True, "chat_id": cid, "token": token}

    @api_router.get("/public/chat/{cid}/messages")
    async def chat_messages(cid: str, token: str = "", after: str = ""):
        await _chat_for_visitor(cid, token)
        q = {"chat_id": cid}
        if after:
            q["at"] = {"$gt": after}
        rows = [r async for r in db.live_messages.find(q, {"_id": 0}).sort("at", 1).limit(200)]
        now = _now()
        await db.live_chats.update_one({"id": cid}, {"$set": {"visitor_seen_at": now, "visitor_last_seen": now}})
        c = await db.live_chats.find_one({"id": cid}, {"_id": 0, "typing_admin_at": 1, "admin_seen_at": 1, "status": 1}) or {}
        return {"ok": True, "messages": [{"from": r["from"], "text": r["text"], "at": r["at"]} for r in rows],
                "agent_typing": _recent(c.get("typing_admin_at"), 6), "admin_seen_at": c.get("admin_seen_at") or "", "status": c.get("status", "acik")}

    @api_router.post("/public/chat/{cid}/typing")
    async def chat_visitor_typing(cid: str, payload: dict):
        await _chat_for_visitor(cid, str(payload.get("token") or ""))
        await db.live_chats.update_one({"id": cid}, {"$set": {"typing_visitor_at": _now(), "visitor_last_seen": _now()}})
        return {"ok": True}

    @api_router.post("/public/chat/{cid}/message")
    async def chat_visitor_msg(cid: str, payload: dict):
        token = str(payload.get("token") or "")
        c = await _chat_for_visitor(cid, token)
        text = str(payload.get("text") or "").strip()[:1000]
        if not text:
            raise HTTPException(422, "Mesaj boş")
        cutoff = (datetime.now(timezone.utc) - timedelta(seconds=60)).isoformat()
        if await db.live_messages.count_documents({"chat_id": cid, "from": "visitor", "at": {"$gt": cutoff}}) >= 15:
            raise HTTPException(429, "Çok hızlı yazıyorsunuz, lütfen biraz bekleyin")
        await _add(cid, "visitor", text)
        await db.live_chats.update_one({"id": cid}, {"$set": {"updated_at": _now(), "last_text": text, "status": "acik"}, "$unset": {"deleted_at": ""}, "$inc": {"unread_admin": 1}})
        await _notify(f"Canlı sohbet: {c.get('name', '')}", text[:120])
        return {"ok": True}

    # ---------- yonetici (panel) ----------
    @api_router.get("/admin/chat/list")
    async def admin_chat_list(user: dict = Depends(get_current_user)):
        await _admin(user)
        rows = [r async for r in db.live_chats.find({"deleted_at": {"$exists": False}}, {"_id": 0, "token": 0}).sort("updated_at", -1).limit(200)]
        for r in rows:
            r["online"] = _recent(r.get("visitor_last_seen"), 15)
        return {"ok": True, "items": rows}

    # --- hazir (otomatik) mesajlar: liste / ekle / duzenle / sil. {cid} yollarindan once tanimli olmali ---
    async def _seed_quick():
        if await db.live_chat_settings.find_one({"id": "quick_seeded"}, {"_id": 1}):
            return
        if await db.live_quick_replies.count_documents({}) == 0:
            for i, (title, text) in enumerate(DEFAULT_QUICK):
                await db.live_quick_replies.insert_one({"id": str(uuid.uuid4()), "title": title, "text": text, "order": i, "at": _now()})
        await db.live_chat_settings.insert_one({"id": "quick_seeded", "at": _now()})

    def _quick_fields(payload):
        title = str(payload.get("title") or "").strip()[:60]
        text = str(payload.get("text") or "").strip()[:1000]
        if not title or not text:
            raise HTTPException(422, "Başlık ve mesaj gerekli")
        return title, text

    @api_router.get("/admin/chat/quick-replies")
    async def quick_list(user: dict = Depends(get_current_user)):
        await _admin(user)
        await _seed_quick()
        rows = [r async for r in db.live_quick_replies.find({}, {"_id": 0}).sort([("order", 1), ("at", 1)]).limit(60)]
        return {"ok": True, "items": rows}

    @api_router.post("/admin/chat/quick-replies")
    async def quick_add(payload: dict, user: dict = Depends(get_current_user)):
        await _admin(user)
        await _seed_quick()
        title, text = _quick_fields(payload)
        if await db.live_quick_replies.count_documents({}) >= 40:
            raise HTTPException(422, "En fazla 40 hazır mesaj eklenebilir")
        last = [r async for r in db.live_quick_replies.find({}, {"_id": 0, "order": 1}).sort("order", -1).limit(1)]
        doc = {"id": str(uuid.uuid4()), "title": title, "text": text, "order": (last[0].get("order", 0) + 1) if last else 0, "at": _now()}
        await db.live_quick_replies.insert_one(dict(doc))
        return {"ok": True, "item": doc}

    @api_router.put("/admin/chat/quick-replies/{qid}")
    async def quick_edit(qid: str, payload: dict, user: dict = Depends(get_current_user)):
        await _admin(user)
        title, text = _quick_fields(payload)
        r = await db.live_quick_replies.update_one({"id": qid}, {"$set": {"title": title, "text": text}})
        if not r.matched_count:
            raise HTTPException(404, "Hazır mesaj bulunamadı")
        return {"ok": True}

    @api_router.delete("/admin/chat/quick-replies/{qid}")
    async def quick_delete(qid: str, user: dict = Depends(get_current_user)):
        # DELETE yalnizca Sahip hesabina acik (governance ara katmani)
        await _admin(user)
        await db.live_quick_replies.delete_one({"id": qid})
        return {"ok": True}

    @api_router.get("/admin/chat/{cid}")
    async def admin_chat_get(cid: str, user: dict = Depends(get_current_user)):
        await _admin(user)
        c = await db.live_chats.find_one({"id": cid}, {"_id": 0, "token": 0})
        if not c:
            raise HTTPException(404, "Sohbet bulunamadı")
        await db.live_chats.update_one({"id": cid}, {"$set": {"unread_admin": 0, "admin_seen_at": _now()}})
        msgs = [r async for r in db.live_messages.find({"chat_id": cid}, {"_id": 0}).sort("at", 1).limit(500)]
        c["online"] = _recent(c.get("visitor_last_seen"), 15)
        c["visitor_typing"] = _recent(c.get("typing_visitor_at"), 6)
        return {"ok": True, "chat": c, "messages": msgs}

    @api_router.post("/admin/chat/{cid}/typing")
    async def admin_chat_typing(cid: str, user: dict = Depends(get_current_user)):
        await _admin(user)
        await db.live_chats.update_one({"id": cid}, {"$set": {"typing_admin_at": _now()}})
        return {"ok": True}

    @api_router.post("/admin/chat/{cid}/reply")
    async def admin_chat_reply(cid: str, payload: dict, user: dict = Depends(get_current_user)):
        await _admin(user)
        text = str(payload.get("text") or "").strip()[:1000]
        if not text:
            raise HTTPException(422, "Mesaj boş")
        if not await db.live_chats.find_one({"id": cid}, {"_id": 1}):
            raise HTTPException(404, "Sohbet bulunamadı")
        await _add(cid, "admin", text)
        await db.live_chats.update_one({"id": cid}, {"$set": {"updated_at": _now(), "last_text": text}})
        return {"ok": True}

    @api_router.post("/admin/chat/{cid}/auto")
    async def admin_chat_auto(cid: str, user: dict = Depends(get_current_user)):
        await _admin(user)
        c = await db.live_chats.find_one({"id": cid}, {"_id": 0, "name": 1})
        if not c:
            raise HTTPException(404, "Sohbet bulunamadı")
        text = AUTO_REPLY.format(ad=_first(c.get("name", "")))
        await _add(cid, "admin", text)
        await db.live_chats.update_one({"id": cid}, {"$set": {"updated_at": _now(), "last_text": text}})
        return {"ok": True}

    @api_router.post("/admin/chat/{cid}/close")
    async def admin_chat_close(cid: str, user: dict = Depends(get_current_user)):
        await _admin(user)
        await db.live_chats.update_one({"id": cid}, {"$set": {"status": "kapali", "updated_at": _now()}})
        return {"ok": True}

    @api_router.delete("/admin/chat/{cid}")
    async def admin_chat_delete(cid: str, user: dict = Depends(get_current_user)):
        # Panelden gizler; mesajlar veritabaninda kalir (sikayet/kayit icin). DELETE yalnizca Sahip hesabina acik.
        await _admin(user)
        r = await db.live_chats.update_one({"id": cid}, {"$set": {"deleted_at": _now(), "status": "kapali"}})
        if not r.matched_count:
            raise HTTPException(404, "Sohbet bulunamadı")
        return {"ok": True}

